#!/usr/bin/env python3
"""
Project X — one-file AI tutor for the Ontario K-12 curriculum.

Data model:  Grade → Subject → Strand (Unit) → Outcome (Lesson) → Question.
Elementary (1-8) and Secondary (9-12), each subject broken into real Ontario
strands. Every strand is a Duolingo-style path of lesson nodes: read the
concept, take a short mini quiz, then a unit-final quiz that puts previously
missed questions first. Every question is tagged with the Ontario Achievement
Chart category it tests (Knowledge/Thinking/Communication/Application).

Two AI backends, chosen per-request or left on "auto":
    - Ollama (default) — calls a locally-running Ollama server (free,
      open-source, nothing leaves your machine).
    - My AI — a small transformer language model written from scratch in
      this file (tokenizer, architecture, training loop, generation — no
      external ML framework beyond PyTorch itself), trained on your own
      curriculum content and whatever you teach it in the Training Studio.
      Weights persist to disk so training survives a restart.
Neither backend calls a paid API. There is no code path in this file that
bills you for anything.

REQUIREMENTS
    Python 3.11+
    pip install -r requirements.txt

    Optional real AI chat (recommended, free):
        ollama pull llama3.2:3b
        ollama pull nomic-embed-text

    Optional "My AI" local model (also free):
        pip install torch

RUN
    python3 tutor.py

FILE MAP (search for these banners — ⌘F / Ctrl+F jumps straight there)
    DB —                        SQLAlchemy tables: Course, Outcome, Concept,
                                Question, Attempt, Mastery, Source, Chunk,
                                LogEvent, TrainingExample.
    SEED                       The curriculum content itself. `SEED` is the
                                original hand-authored dict; `ONTARIO_*` lists
                                further down are the same shape, merged in by
                                seed_if_empty() — see "Extending the
                                curriculum" in README.md for the exact format.
    MY AI                      The from-scratch local model: tokenizer,
                                MyAIModel (tiny GPT), training + generation.
    INGEST + LLM                Ollama helpers, RAG retrieval, the tutor's
                                system prompt (build_system_prompt).
    FASTAPI                    All HTTP routes — /api/courses, /api/chat,
                                /api/attempts, /api/training, /api/my-ai/*,
                                /api/sources, /api/log.
    HTML_PAGE                   The entire frontend: CSS in <style>, app
                                logic in <script>. Vanilla JS, no build step,
                                no framework — h() is a tiny hyperscript
                                helper; render() re-renders the whole tree
                                from `state` on every change (see the STATE
                                section near the top of the script).
"""

from __future__ import annotations
import os, re, shutil, sys, threading, time, webbrowser
# numpy and torch each bundle their own OpenMP runtime on macOS; loading both
# in one process aborts with "OMP: Error #15" unless this is set BEFORE either
# is imported, and can still segfault under real load ("OMP: Error #179")
# unless each runtime is pinned to a single thread. Harmless elsewhere — this
# is the standard workaround for the numpy+torch macOS conflict.
os.environ.setdefault("KMP_DUPLICATE_LIB_OK", "TRUE")
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("MKL_NUM_THREADS", "1")
from contextlib import asynccontextmanager
from datetime import datetime
from pathlib import Path
from typing import Literal

import httpx, numpy as np
from fastapi import Depends, FastAPI, File, Form, HTTPException, UploadFile
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse
from pydantic import BaseModel
from sqlalchemy import (JSON, Boolean, DateTime, Float, ForeignKey, Integer,
                        String, Text, create_engine)
from sqlalchemy.orm import (DeclarativeBase, Mapped, Session, mapped_column,
                            relationship, sessionmaker)


HERE = Path(__file__).parent.resolve()
OLLAMA_HOST = os.environ.get("OLLAMA_HOST", "http://localhost:11434").rstrip("/")
OLLAMA_CHAT_MODEL = os.environ.get("OLLAMA_CHAT_MODEL", "llama3.2:3b")
OLLAMA_EMBED_MODEL = os.environ.get("OLLAMA_EMBED_MODEL", "nomic-embed-text")


def _pick_writable_paths() -> tuple[Path, Path]:
    """Return (db_path, upload_dir), preferring the project folder but falling
    back to ~/Library/Application Support/project-x if the project folder isn't
    reliably writable (macOS Full Disk Access edge cases, paths with special
    characters, read-only mounts, etc.). SQLite silently opens files read-only
    when write permission is unclear, so we do a real write test up front."""
    for base in (HERE, Path.home() / "Library" / "Application Support" / "project-x"):
        try:
            base.mkdir(parents=True, exist_ok=True)
            probe = base / ".write_probe"
            probe.write_text("ok")
            probe.unlink()
            db = base / "tutor.db"
            up = base / "uploads"
            up.mkdir(exist_ok=True)
            # If a legacy DB exists here, make sure it's writable.
            if db.exists():
                try: db.chmod(0o644)
                except Exception: pass
            if base != HERE:
                print(f"⚠  project folder not writable — using {base}", file=sys.stderr)
            return db, up
        except (PermissionError, OSError):
            continue
    raise RuntimeError("no writable directory available for tutor.db")


DB_PATH, UPLOAD_DIR = _pick_writable_paths()


# ═════════════════════════════════════════════════════════════════════════════
#  DB — WAL mode + safe pragmas so concurrent request handlers don't collide
# ═════════════════════════════════════════════════════════════════════════════
from sqlalchemy import event as _sa_event
from sqlalchemy.engine.url import URL as _URL

# Build the URL through SQLAlchemy's URL helper — handles paths with colons,
# spaces, and other characters that the raw sqlite:/// string can mangle.
_db_url = _URL.create("sqlite", database=str(DB_PATH))
engine = create_engine(_db_url, connect_args={"check_same_thread": False, "timeout": 30})

@_sa_event.listens_for(engine, "connect")
def _sqlite_pragmas(dbapi_connection, connection_record):
    cur = dbapi_connection.cursor()
    try:
        cur.execute("PRAGMA journal_mode=WAL")     # concurrent readers + writers
        cur.execute("PRAGMA synchronous=NORMAL")   # good balance
        cur.execute("PRAGMA busy_timeout=30000")   # wait 30s on lock
    finally:
        cur.close()

SessionLocal = sessionmaker(bind=engine, autoflush=False, autocommit=False)

class Base(DeclarativeBase): pass

class Course(Base):
    __tablename__ = "courses"
    id: Mapped[str] = mapped_column(String(64), primary_key=True)
    label: Mapped[str] = mapped_column(String(255))     # display name (e.g. "Math" or "MATH 106")
    level: Mapped[str] = mapped_column(String(16))      # elementary | secondary | uni
    grade: Mapped[int] = mapped_column(Integer)         # 1..12 for K-12; 13 for UW-1A, 14 for UW-1B
    subject: Mapped[str] = mapped_column(String(32))    # math | english | french | science | cs | physics | chemistry
    outcomes: Mapped[list["Outcome"]] = relationship(back_populates="course", cascade="all, delete-orphan")

class Outcome(Base):
    __tablename__ = "outcomes"
    id: Mapped[str] = mapped_column(String(64), primary_key=True)
    course_id: Mapped[str] = mapped_column(ForeignKey("courses.id"))
    code: Mapped[str] = mapped_column(String(32))
    name: Mapped[str] = mapped_column(String(255))
    blurb: Mapped[str] = mapped_column(Text)
    strand: Mapped[str] = mapped_column(String(64))     # curriculum strand
    course: Mapped[Course] = relationship(back_populates="outcomes")
    concepts: Mapped[list["Concept"]] = relationship(back_populates="outcome", cascade="all, delete-orphan")
    questions: Mapped[list["Question"]] = relationship(back_populates="outcome", cascade="all, delete-orphan")

class Concept(Base):
    __tablename__ = "concepts"
    id: Mapped[str] = mapped_column(String(64), primary_key=True)
    outcome_id: Mapped[str] = mapped_column(ForeignKey("outcomes.id"))
    name: Mapped[str] = mapped_column(String(255))
    sub: Mapped[str] = mapped_column(String(255))
    one_liner: Mapped[str] = mapped_column(Text)
    body: Mapped[str] = mapped_column(Text)
    worked: Mapped[str] = mapped_column(Text)
    misconception: Mapped[str] = mapped_column(Text)
    outcome: Mapped[Outcome] = relationship(back_populates="concepts")

class Question(Base):
    __tablename__ = "questions"
    id: Mapped[str] = mapped_column(String(64), primary_key=True)
    outcome_id: Mapped[str] = mapped_column(ForeignKey("outcomes.id"))
    kind: Mapped[str] = mapped_column(String(16))         # mc | numeric | flashcard
    diff: Mapped[int] = mapped_column(Integer)
    prompt: Mapped[str] = mapped_column(Text)
    choices: Mapped[list | None] = mapped_column(JSON, nullable=True)
    answer: Mapped[str] = mapped_column(Text)
    tolerance: Mapped[float | None] = mapped_column(Float, nullable=True)
    hints: Mapped[list] = mapped_column(JSON, default=list)
    solution: Mapped[str] = mapped_column(Text)           # always shown — the "why"
    # Ontario Achievement Chart category: K (Knowledge & Understanding),
    # T (Thinking), C (Communication), A (Application). Defaulted by strand
    # at seed time when not set explicitly — see STRAND_CATEGORY.
    category: Mapped[str] = mapped_column(String(1), default="K")
    outcome: Mapped[Outcome] = relationship(back_populates="questions")

class Attempt(Base):
    __tablename__ = "attempts"
    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    outcome_id: Mapped[str] = mapped_column(ForeignKey("outcomes.id"))
    question_id: Mapped[str] = mapped_column(ForeignKey("questions.id"))
    mode: Mapped[str] = mapped_column(String(16), default="practice")  # practice | flashcard | blitz
    correct: Mapped[bool] = mapped_column(Boolean)
    hints_used: Mapped[int] = mapped_column(Integer, default=0)
    created_at: Mapped[datetime] = mapped_column(DateTime, default=datetime.utcnow)

class Mastery(Base):
    __tablename__ = "mastery"
    outcome_id: Mapped[str] = mapped_column(ForeignKey("outcomes.id"), primary_key=True)
    score: Mapped[float] = mapped_column(Float, default=0.0)
    attempts: Mapped[int] = mapped_column(Integer, default=0)
    correct: Mapped[int] = mapped_column(Integer, default=0)
    updated_at: Mapped[datetime] = mapped_column(DateTime, default=datetime.utcnow)

class Source(Base):
    __tablename__ = "sources"
    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    outcome_id: Mapped[str | None] = mapped_column(ForeignKey("outcomes.id"), nullable=True)
    title: Mapped[str] = mapped_column(String(255))
    kind: Mapped[str] = mapped_column(String(32))
    bytes_size: Mapped[int] = mapped_column(Integer, default=0)
    chunks_n: Mapped[int] = mapped_column(Integer, default=0)
    created_at: Mapped[datetime] = mapped_column(DateTime, default=datetime.utcnow)
    chunks: Mapped[list["Chunk"]] = relationship(back_populates="source", cascade="all, delete-orphan")

class Chunk(Base):
    __tablename__ = "chunks"
    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    source_id: Mapped[int] = mapped_column(ForeignKey("sources.id"))
    outcome_id: Mapped[str | None] = mapped_column(ForeignKey("outcomes.id"), nullable=True)
    ord: Mapped[int] = mapped_column(Integer)
    text: Mapped[str] = mapped_column(Text)
    embedding: Mapped[list | None] = mapped_column(JSON, nullable=True)
    source: Mapped[Source] = relationship(back_populates="chunks")

class LogEvent(Base):
    __tablename__ = "log_events"
    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    kind: Mapped[str] = mapped_column(String(32))
    detail: Mapped[str] = mapped_column(Text)
    outcome_id: Mapped[str | None] = mapped_column(ForeignKey("outcomes.id"), nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime, default=datetime.utcnow)

class TrainingExample(Base):
    """A manually-taught Q&A pair. Injected as a few-shot example into every
    chat system prompt (globally, or scoped to one outcome) — this is the
    persistent 'trained data' the tutor remembers across restarts."""
    __tablename__ = "training_examples"
    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    outcome_id: Mapped[str | None] = mapped_column(ForeignKey("outcomes.id"), nullable=True)
    prompt: Mapped[str] = mapped_column(Text)
    response: Mapped[str] = mapped_column(Text)
    note: Mapped[str] = mapped_column(Text, default="")     # optional: why this example matters
    active: Mapped[bool] = mapped_column(Boolean, default=True)
    created_at: Mapped[datetime] = mapped_column(DateTime, default=datetime.utcnow)


