ALL_UNIT_ROWS = ONTARIO_MATH_ELEM + ONTARIO_LANG_ELEM + ONTARIO_SCI_ELEM + ONTARIO_MATH_SECONDARY + ONTARIO_SECONDARY_BROAD + TESTPREP + ELEM_MATH_1 + ELEM_MATH_2 + SEC_MATH_EXPAND + ELEM_SCI_1 + ELEM_SCI_2 + ELEM_SCI_TOPUP + ELEM_ENG_1 + ELEM_ENG_2 + SEC_ENG_1 + SEC_ENG_2 + SEC_SCI + SEC_BIO_CHEM + SEC_PHYS + SEC_BIZ_CS + FRENCH_ELEM + FRENCH_SEC + CIVICS_GEO_HIST


def _extra_units_by_course():
    """Group the ontario rows by course_id and turn each into an _o() outcome."""
    from collections import OrderedDict
    out: dict[str, list[tuple[str, dict]]] = {}
    for row in ALL_UNIT_ROWS:
        cid, code, name, blurb, strand, body, worked, qs = row
        concepts = [_c(code.lower(), name, strand,
                       body.split(". ")[0][:110],
                       body,
                       worked,
                       "Take your time. Read carefully.")]
        questions = []
        for i, q in enumerate(qs):
            prompt, ans, choices, kind, diff, hint, sol = q
            questions.append(_q(f"{code.lower()}-q{i+1}", kind, diff, prompt, ans,
                                [hint], sol,
                                choices=choices, tol=(0.001 if kind == "numeric" else None)))
        out.setdefault(cid, []).append((code, _o(name, blurb, strand, concepts, questions)))
    return out




def seed_if_empty():
    """Create tables if needed, then load the curriculum on a fresh database
    only — never touches an existing one. Merges two content sources: the
    hand-authored SEED dict and the compact ONTARIO_* row lists (expanded by
    _extra_units_by_course()). Where both define the same outcome code, SEED
    wins. To reseed with new content, stop the app and delete tutor.db."""
    Base.metadata.create_all(bind=engine)
    with SessionLocal() as db:
        if db.query(Course).count() > 0:
            return
        extra = _extra_units_by_course()
        # Merge extras into SEED's outcomes so unit ordering is stable
        merged: dict = {}
        for cid, c in SEED.items():
            merged[cid] = dict(c)
            merged[cid]["outcomes"] = dict(c["outcomes"])
        for cid, rows in extra.items():
            if cid not in merged:
                # Infer minimal course metadata from cid ("e-gN-subject" or "s-gN-subject")
                parts = cid.split("-")
                level = "elementary" if parts[0] == "e" else "secondary"
                grade = int(parts[1][1:])
                subject = "-".join(parts[2:])
                sub_label = {"math":"Math","english":"Language","french":"French","science":"Science",
                             "chemistry":"Chemistry","physics":"Physics","biology":"Biology",
                             "cs":"Computer Science","history":"History","geography":"Geography",
                             "business":"Business","civics":"Civics",
                             "testprep-quant":"Test Prep · Math", "testprep-verbal":"Test Prep · Reading & Writing",
                             "testprep-pisa":"Test Prep · PISA-Style"}.get(subject, subject.title())
                merged[cid] = {"label": sub_label, "level": level, "grade": grade,
                               "subject": subject, "outcomes": {}}
            for oid, outcome_dict in rows:
                # Skip if outcome already exists (SEED takes priority)
                if oid in merged[cid]["outcomes"]:
                    continue
                merged[cid]["outcomes"][oid] = outcome_dict

        for cid, c in merged.items():
            course = Course(id=cid, label=c["label"], level=c["level"],
                            grade=c["grade"], subject=c["subject"])
            db.add(course)
            for oid, o in c["outcomes"].items():
                outcome = Outcome(id=oid, course_id=cid, code=oid,
                                  name=o["name"], blurb=o["blurb"], strand=o["strand"])
                db.add(outcome)
                for concept in o["concepts"]:
                    db.add(Concept(outcome_id=oid, **concept))
                default_cat = STRAND_CATEGORY.get(o["strand"], "K")
                for q in o["questions"]:
                    q = dict(q)
                    if not q.get("category"):
                        q["category"] = default_cat
                    db.add(Question(outcome_id=oid, **q))
        db.commit()


# ═════════════════════════════════════════════════════════════════════════════
#  MY AI — a small custom language model, trained on THIS app's own content and
#  saved to disk. Pure local PyTorch, no Anthropic, no Ollama, no network call
#  of any kind — the architecture, tokenizer, training loop, and generation
#  code all live right here in this file. Training data = every concept in the
#  curriculum + every example dialogue + everything you teach it in the
#  Training Studio. Be honest with yourself about scale: a model this small,
#  trained on a few hundred KB of text on a laptop, will sound rougher than
#  Ollama's llama3.2 — it is a real, from-scratch, fully-local, fully-yours
#  model, not a claim that it rivals a lab-scale LLM. Quality grows with how
#  much you teach it.
# ═════════════════════════════════════════════════════════════════════════════
try:
    import torch
    import torch.nn as nn
    import torch.nn.functional as Fnn
    torch.set_num_threads(1)   # belt-and-suspenders alongside OMP_NUM_THREADS=1 above
    TORCH_OK = True
except Exception:
    TORCH_OK = False

MYAI_DIR = DB_PATH.parent / "my_ai"
MYAI_WEIGHTS = MYAI_DIR / "model.pt"
MYAI_VOCAB = MYAI_DIR / "vocab.json"
MYAI_META = MYAI_DIR / "meta.json"

# Tiny GPT hyperparameters — sized to train in minutes on a CPU/Apple Silicon
# laptop against a few hundred KB of text. Bump these up once you have a lot
# more training data and are willing to wait longer.
MYAI_BLOCK = 96          # context window (tokens)
MYAI_EMBD = 128
MYAI_HEADS = 4
MYAI_LAYERS = 4
MYAI_MAX_VOCAB = 6000

_TOKEN_RE = re.compile(r"[A-Za-z]+(?:'[A-Za-z]+)?|\d+(?:\.\d+)?|[^\sA-Za-z0-9]")

def _myai_tokenize(text: str) -> list[str]:
    return _TOKEN_RE.findall(text)


class _MyAIVocab:
    def __init__(self, tokens: list[str]):
        from collections import Counter
        counts = Counter(tokens)
        specials = ["<pad>", "<unk>", "<eos>"]
        common = [w for w, _ in counts.most_common(MYAI_MAX_VOCAB - len(specials))]
        self.itos = specials + common
        self.stoi = {w: i for i, w in enumerate(self.itos)}
        self.unk = self.stoi["<unk>"]
        self.pad = self.stoi["<pad>"]
        self.eos = self.stoi["<eos>"]

    def encode(self, text: str) -> list[int]:
        return [self.stoi.get(t, self.unk) for t in _myai_tokenize(text)]

    def decode(self, ids: list[int]) -> str:
        words = [self.itos[i] for i in ids if i not in (self.pad, self.eos)]
        out = ""
        for w in words:
            if w and w[0].isalnum() and out and out[-1] not in ("(", "["):
                out += " "
            out += w
        return out.strip()

    def save(self, path: Path):
        import json
        path.write_text(json.dumps({"itos": self.itos}))

    @classmethod
    def load(cls, path: Path) -> "_MyAIVocab":
        import json
        data = json.loads(path.read_text())
        self = cls.__new__(cls)
        self.itos = data["itos"]
        self.stoi = {w: i for i, w in enumerate(self.itos)}
        self.unk = self.stoi.get("<unk>", 1)
        self.pad = self.stoi.get("<pad>", 0)
        self.eos = self.stoi.get("<eos>", 2)
        return self


if TORCH_OK:
    class _MyAIBlock(nn.Module):
        def __init__(self, embd, heads, block):
            super().__init__()
            self.ln1 = nn.LayerNorm(embd)
            self.attn = nn.MultiheadAttention(embd, heads, batch_first=True)
            self.ln2 = nn.LayerNorm(embd)
            self.mlp = nn.Sequential(nn.Linear(embd, 4*embd), nn.GELU(), nn.Linear(4*embd, embd))
            mask = torch.triu(torch.ones(block, block), diagonal=1).bool()
            self.register_buffer("mask", mask)

        def forward(self, x):
            T = x.size(1)
            h = self.ln1(x)
            a, _ = self.attn(h, h, h, attn_mask=self.mask[:T, :T], need_weights=False)
            x = x + a
            x = x + self.mlp(self.ln2(x))
            return x

    class MyAIModel(nn.Module):
        def __init__(self, vocab_size, embd=MYAI_EMBD, heads=MYAI_HEADS, layers=MYAI_LAYERS, block=MYAI_BLOCK):
            super().__init__()
            self.block = block
            self.tok_emb = nn.Embedding(vocab_size, embd)
            self.pos_emb = nn.Embedding(block, embd)
            self.blocks = nn.ModuleList([_MyAIBlock(embd, heads, block) for _ in range(layers)])
            self.ln_f = nn.LayerNorm(embd)
            self.head = nn.Linear(embd, vocab_size, bias=False)

        def forward(self, idx, targets=None):
            B, T = idx.shape
            pos = torch.arange(T, device=idx.device)
            x = self.tok_emb(idx) + self.pos_emb(pos)[None, :, :]
            for blk in self.blocks:
                x = blk(x)
            x = self.ln_f(x)
            logits = self.head(x)
            loss = None
            if targets is not None:
                loss = Fnn.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1)
            return logits, loss

        @torch.no_grad()
        def generate(self, idx, max_new_tokens, eos_id, temperature=0.8, top_k=40):
            self.eval()
            for _ in range(max_new_tokens):
                idx_cond = idx[:, -self.block:]
                logits, _ = self(idx_cond)
                logits = logits[:, -1, :] / max(temperature, 1e-4)
                if top_k:
                    v, _ = torch.topk(logits, min(top_k, logits.size(-1)))
                    logits[logits < v[:, [-1]]] = -float("inf")
                probs = Fnn.softmax(logits, dim=-1)
                nxt = torch.multinomial(probs, 1)
                idx = torch.cat([idx, nxt], dim=1)
                if nxt.item() == eos_id:
                    break
            return idx


def myai_status() -> dict:
    if not TORCH_OK:
        return {"available": False, "reason": "PyTorch isn't installed — run: pip install torch",
                "trained": False}
    trained = MYAI_WEIGHTS.exists() and MYAI_VOCAB.exists()
    meta = {}
    if MYAI_META.exists():
        import json
        try: meta = json.loads(MYAI_META.read_text())
        except Exception: meta = {}
    return {"available": True, "trained": trained,
            "vocab_size": meta.get("vocab_size"), "examples": meta.get("examples"),
            "corpus_chars": meta.get("corpus_chars"), "epochs": meta.get("epochs"),
            "trained_at": meta.get("trained_at"), "params": meta.get("params")}


def myai_build_corpus(db: Session) -> str:
    """Everything the app knows, turned into 'User: ... \\nTutor: ...' style
    training text: curriculum concepts, worked examples, misconceptions, the
    built-in example dialogues, and every Training Studio Q&A pair."""
    parts = []
    for o in db.query(Outcome).all():
        for c in o.concepts:
            parts.append(f"User: Explain {c.name}.\nTutor: {c.body} {c.worked} {c.misconception}\n")
        if o.blurb:
            parts.append(f"User: What is {o.name}?\nTutor: {o.blurb}\n")
    for conv in CONVERSATIONS.values():
        buf = []
        for m in conv:
            role = "User" if m["role"] == "user" else "Tutor"
            buf.append(f"{role}: {m['content']}")
        parts.append("\n".join(buf) + "\n")
    for t in db.query(TrainingExample).filter(TrainingExample.active == True).all():
        parts.append(f"User: {t.prompt}\nTutor: {t.response}\n")
    return "\n".join(parts)


_myai_train_state = {"running": False, "progress": 0.0, "loss": None, "error": None}

def myai_train_sync(db: Session, epochs: int = 8):
    """Blocking training run — small enough corpus that this finishes in
    well under a minute on CPU for a few hundred KB of text. Saves weights +
    vocab to disk so the model survives a restart (the 'keep the trained
    data' part)."""
    if not TORCH_OK:
        raise RuntimeError("PyTorch isn't installed")
    _myai_train_state.update(running=True, progress=0.0, loss=None, error=None)
    try:
        corpus = myai_build_corpus(db)
        if len(corpus) < 200:
            raise RuntimeError("Not enough training text yet — add a few Training Studio examples first")
        tokens = _myai_tokenize(corpus)
        vocab = _MyAIVocab(tokens)
        ids = torch.tensor(vocab.encode(corpus), dtype=torch.long)

        device = "mps" if torch.backends.mps.is_available() else ("cuda" if torch.cuda.is_available() else "cpu")
        model = MyAIModel(len(vocab.itos)).to(device)
        opt = torch.optim.AdamW(model.parameters(), lr=3e-4)

        block = MYAI_BLOCK
        n = ids.size(0)
        if n <= block + 1:
            raise RuntimeError("Training text is too short — add more material or Q&A examples")
        batch_size = 32
        steps_per_epoch = max(20, min(150, n // block))

        model.train()
        last_loss = None
        for ep in range(epochs):
            for step in range(steps_per_epoch):
                starts = torch.randint(0, n - block - 1, (batch_size,))
                xb = torch.stack([ids[s:s+block] for s in starts]).to(device)
                yb = torch.stack([ids[s+1:s+block+1] for s in starts]).to(device)
                _, loss = model(xb, yb)
                opt.zero_grad(set_to_none=True)
                loss.backward()
                opt.step()
                last_loss = loss.item()
            _myai_train_state["progress"] = (ep + 1) / epochs
            _myai_train_state["loss"] = last_loss

        MYAI_DIR.mkdir(parents=True, exist_ok=True)
        torch.save(model.state_dict(), MYAI_WEIGHTS)
        vocab.save(MYAI_VOCAB)
        import json
        n_params = sum(p.numel() for p in model.parameters())
        MYAI_META.write_text(json.dumps({
            "vocab_size": len(vocab.itos), "examples": len(corpus.split("User:")) - 1,
            "corpus_chars": len(corpus), "epochs": epochs,
            "trained_at": datetime.utcnow().isoformat(), "params": n_params,
        }))
        _myai_train_state.update(running=False, progress=1.0, error=None)
    except Exception as e:
        _myai_train_state.update(running=False, error=str(e))
        raise


_myai_cache = {"model": None, "vocab": None, "device": None}

def myai_reply(system: str, messages: list[dict]) -> str:
    if not TORCH_OK:
        raise RuntimeError("PyTorch isn't installed")
    if not (MYAI_WEIGHTS.exists() and MYAI_VOCAB.exists()):
        raise RuntimeError("My AI hasn't been trained yet")
    if _myai_cache["model"] is None:
        vocab = _MyAIVocab.load(MYAI_VOCAB)
        device = "mps" if torch.backends.mps.is_available() else ("cuda" if torch.cuda.is_available() else "cpu")
        model = MyAIModel(len(vocab.itos)).to(device)
        model.load_state_dict(torch.load(MYAI_WEIGHTS, map_location=device))
        model.eval()
        _myai_cache.update(model=model, vocab=vocab, device=device)
    model, vocab, device = _myai_cache["model"], _myai_cache["vocab"], _myai_cache["device"]

    last_user = next((m["content"] for m in reversed(messages) if m["role"] == "user"), "")
    prompt = f"User: {last_user}\nTutor:"
    ids = vocab.encode(prompt)[-MYAI_BLOCK:]
    if not ids: ids = [vocab.unk]
    idx = torch.tensor([ids], dtype=torch.long).to(device)
    out = model.generate(idx, max_new_tokens=60, eos_id=vocab.eos)
    reply = vocab.decode(out[0, len(ids):].tolist())
    return reply.strip() or "I'm still learning — teach me more examples in the Training Studio and try again."


# ═════════════════════════════════════════════════════════════════════════════
#  INGEST + LLM
# ═════════════════════════════════════════════════════════════════════════════
def extract_text(path: Path, ext: str) -> str:
    ext = ext.lower().lstrip(".")
    if ext == "pdf":
        from pypdf import PdfReader
        reader = PdfReader(str(path))
        parts = []
        for i, page in enumerate(reader.pages):
            try: t = page.extract_text() or ""
            except Exception: t = ""
            if t.strip(): parts.append(f"[p.{i+1}]\n{t}")
        return "\n\n".join(parts)
    if ext == "docx":
        from docx import Document
        doc = Document(str(path))
        return "\n\n".join(p.text.strip() for p in doc.paragraphs if p.text.strip())
    if ext in {"txt", "md"}:
        return path.read_text(encoding="utf-8", errors="replace")
    raise ValueError(f"unsupported .{ext}")


def chunk_text(text: str) -> list[str]:
    paras = [p.strip() for p in re.split(r"\n\s*\n+", text.replace("\r", "")) if p.strip()]
    if not paras: return []
    TGT, OVL = 500, 60
    tok = lambda s: max(1, len(s) // 4)
    out, buf, bt = [], [], 0
    def flush():
        nonlocal buf, bt
        if not buf: return
        out.append("\n\n".join(buf))
        tail, tt = [], 0
        for p in reversed(buf):
            pt = tok(p)
            if tt + pt > OVL: break
            tail.insert(0, p); tt += pt
        buf = tail; bt = tt
    for p in paras:
        pt = tok(p)
        if bt + pt > TGT and buf: flush()
        buf.append(p); bt += pt
    if buf and (bt > OVL or not out): flush()
    return out


# In "auto" mode, chat_reply() calls this before every single message (dock
# chat, training test chat, simplify button, tutor panel all route through
# it) — a raw health check would mean one extra Ollama round trip per
# message. A short cache keeps the check honest (state changes reflect
# within a couple seconds) without hammering /api/tags on every keystroke.
_ollama_alive_cache: dict = {"result": None, "at": 0.0}
_OLLAMA_ALIVE_TTL = 2.5  # seconds

async def ollama_alive() -> tuple[bool, bool, bool]:
    now = time.monotonic()
    cached = _ollama_alive_cache["result"]
    if cached is not None and (now - _ollama_alive_cache["at"]) < _OLLAMA_ALIVE_TTL:
        return cached
    try:
        async with httpx.AsyncClient(timeout=3.0) as c:
            r = await c.get(f"{OLLAMA_HOST}/api/tags")
            if r.status_code != 200:
                result = (False, False, False)
            else:
                names_full = {m.get("name", "") for m in r.json().get("models", [])}
                names_base = {n.split(":")[0] for n in names_full}
                chat_ok = OLLAMA_CHAT_MODEL in names_full or OLLAMA_CHAT_MODEL.split(":")[0] in names_base
                emb_ok = OLLAMA_EMBED_MODEL in names_full or OLLAMA_EMBED_MODEL.split(":")[0] in names_base
                result = (True, chat_ok, emb_ok)
    except Exception:
        result = (False, False, False)
    _ollama_alive_cache["result"] = result
    _ollama_alive_cache["at"] = now
    return result


async def ollama_chat(system: str, messages: list[dict]) -> str:
    body = {"model": OLLAMA_CHAT_MODEL,
            "messages": [{"role":"system","content":system}, *messages],
            "stream": False, "options":{"temperature":0.5}}
    async with httpx.AsyncClient(timeout=120.0) as c:
        r = await c.post(f"{OLLAMA_HOST}/api/chat", json=body)
        r.raise_for_status()
        return r.json()["message"]["content"]


async def ollama_embed(texts: list[str]) -> list[list[float]]:
    out = []
    async with httpx.AsyncClient(timeout=60.0) as c:
        for t in texts:
            r = await c.post(f"{OLLAMA_HOST}/api/embeddings",
                             json={"model":OLLAMA_EMBED_MODEL, "prompt":t})
            r.raise_for_status()
            out.append(r.json()["embedding"])
    return out


def build_system_prompt(level: str, mode: str, outcome_code: str, outcome_name: str,
                        course_label: str, grade: int, retrieved: list[dict],
                        training: list[dict] | None = None) -> str:
    """Assemble the full system prompt for one chat turn: a voice calibrated
    to grade level, the tutor's standing behavioural rules (plain language,
    diagnose-first, use pictures), practice-vs-homework rules, any retrieved
    content-library excerpts (RAG), and any Training Studio examples relevant
    to this outcome. Called fresh on every request — nothing here is cached,
    since the outcome/mode/retrieved context changes turn to turn."""
    # Voice per level — vocabulary and analogies calibrated, never patronising.
    if level == "elementary":
        voice = (f"You are a warm, patient tutor for a Grade {grade} student (about age {grade+5}). "
                 "Use short simple sentences. Reach for concrete analogies they can picture — pizza slices, "
                 "bags of apples, jumping. Never talk down. Encourage effort, not intelligence.")
    elif level == "secondary":
        voice = (f"You are a clear, respectful tutor for a Grade {grade} high-school student. "
                 "Use standard vocabulary and define new terms as you introduce them. Show reasoning steps "
                 "explicitly. Treat the student as capable.")
    else:
        voice = ("You are a precise, formal tutor for an undergraduate. Use standard technical vocabulary "
                 "and formal notation. Prefer definitions and worked examples over folksy analogies. "
                 "Be terse where terseness is clearer.")

    # Core principles embedded into every response — the 10 qualities of a good tutor.
    principles = (
        "Follow these principles on every turn:\n"
        "• DIAGNOSE FIRST. Before you explain, briefly probe what the student already knows or where they got "
        "  stuck. Ask ONE targeted question first, then respond. Never assume the gap.\n"
        "• PLAIN, SIMPLE ENGLISH — ALWAYS. One idea per sentence. Max ~15 words a sentence. No jargon without "
        "  defining it the moment you use it, in the same breath, in everyday words. Never stack two new ideas "
        "  in one sentence. If a smart 10-year-old couldn't follow the sentence, rewrite it simpler.\n"
        "• EXPLAIN THE WHY, not just the how. If you give a step, say why that step is the right move — in one "
        "  short simple sentence, not a paragraph.\n"
        "• SWITCH REGISTERS IF NEEDED. If one explanation doesn't land, offer a different angle — an analogy, "
        "  a worked example, a picture-in-words, or a first-principles derivation. Keep each attempt short.\n"
        "• BE PATIENT WITH REPETITION. If the student asks something you already covered, re-explain it "
        "  without any hint of annoyance and try a different framing this time.\n"
        "• PLAN, BUT FLEX. Have a rough shape for the answer, but drop it instantly if the student surfaces "
        "  a more fundamental confusion — chase THAT down first.\n"
        "• ADMIT UNCERTAINTY. If you're not sure, say so and reason it out loud. Never bluff.\n"
        "• PRACTICE OUTSIDE THE TURN. When it fits, suggest a specific practice question or exercise the "
        "  student can try between messages — the best learning compounds outside the session.\n"
        "• SHOW MULTIPLICATION AS REPEATED ADDING. Any time you multiply, write it out: '5 × 3 = 3 + 3 + 3 + 3 + 3 = 15'. "
        "  This is non-optional for elementary students.\n"
        "• DRAW A PICTURE WHENEVER IT WOULD HELP — DO THIS OFTEN, NOT RARELY. The interface AUTOMATICALLY turns "
        "  certain patterns in your text into a diagram next to your message. Reach for one of these on purpose "
        "  whenever the topic fits, don't wait to be asked:\n"
        "    - Multiplication / grouping → write '5 × 3' or '3 groups of 4' → draws grouped dots\n"
        "    - Fractions → write '3/4' → draws a divided circle\n"
        "    - Negative numbers, inequalities, or 'where a number sits' → write a phrase like "
        "      'on a number line, -3 is left of 2' → draws a number line\n"
        "    - Ratios or comparing two amounts → write 'ratio 3:2' → draws a proportional bar model\n"
        "    - Rectangles/triangles and their sides → write 'rectangle with length 6 and width 4' or "
        "      'triangle with base 6 and height 4' → draws a labeled shape\n"
        "  Never say 'I can't show pictures' or 'I can't send images' — you CAN, by writing the pattern above. "
        "  If a picture would make an explanation click faster than more words, use the picture.\n"
    )

    if mode == "practice":
        rules = ("Practice mode: NEVER just hand over the final answer. Guide with the smallest possible "
                 "hint first, then a bigger one only if asked, then a walk-through only when the student "
                 "confirms they've tried. The point is the process, not the answer.")
    else:
        rules = ("Homework help mode: the student is under time pressure. Show the reasoning steps clearly "
                 "and quickly, but STILL show HOW the answer follows step-by-step. Never a bare answer. "
                 "Flag the one common mistake for this kind of problem as you go.")

    ctx = ""
    if retrieved:
        ctx = "\n\nUploaded material (cite as [title] when you use it):\n" + \
              "\n\n".join(f"[{r['title']}]  {r['text']}" for r in retrieved)

    trained = ""
    if training:
        examples = "\n\n".join(f"Student: {t['prompt']}\nGood tutor reply: {t['response']}" for t in training)
        trained = ("\n\nYou were specifically taught to answer like this in similar situations — match this "
                   f"style and level of simplicity when it applies:\n\n{examples}")

    return (f"{voice}\n\n{principles}\n{rules}\n\n"
            f"Current outcome: {outcome_code} — {outcome_name}\nCourse: {course_label}{ctx}{trained}")


FALLBACK_REPLY = {
    "practice": ("I'm in scripted mode — no AI is running. Try the hints on any practice question, "
                 "or read the Concept Explainer. To turn me on: install Ollama and run "
                 "'ollama pull llama3.2:3b'."),
    "homework": ("Homework mode needs the AI. Install Ollama and pull llama3.2:3b, then I can "
                 "walk through reasoning directly."),
}


async def chat_reply(system: str, messages: list[dict], mode: str, engine: str = "auto") -> tuple[str, str]:
    """engine: 'auto' (Ollama if running, else scripted fallback), 'ollama'
    (force Ollama, error if unavailable), or 'my_ai' (force the local
    from-scratch model, error if untrained)."""
    if engine == "my_ai":
        return myai_reply(system, messages), "my_ai"
    if engine == "ollama":
        return await ollama_chat(system, messages), "ollama"
    alive, chat_ok, _ = await ollama_alive()
    if alive and chat_ok:
        try:
            return await ollama_chat(system, messages), "ollama"
        except Exception:
            pass
    return FALLBACK_REPLY[mode], "fallback"


def cosine_sim(a: np.ndarray, B: np.ndarray) -> np.ndarray:
    an = a / (np.linalg.norm(a) + 1e-9)
    Bn = B / (np.linalg.norm(B, axis=1, keepdims=True) + 1e-9)
    return Bn @ an


async def retrieve(db: Session, query: str, outcome_id: str | None, top_k: int = 3) -> list[dict]:
    rows = db.query(Chunk).filter((Chunk.outcome_id == outcome_id) | (Chunk.outcome_id.is_(None))).all()
    if not rows: return []
    if any(c.embedding for c in rows):
        try:
            q_vec = (await ollama_embed([query]))[0]
            q_arr = np.array(q_vec, dtype=np.float32)
            usable = [c for c in rows if c.embedding]
            M = np.array([c.embedding for c in usable], dtype=np.float32)
            sims = cosine_sim(q_arr, M)
            order = np.argsort(-sims)[:top_k]
            hits = []
            for idx in order:
                s = float(sims[idx])
                if s < 0.30: continue
                c = usable[idx]
                hits.append({"chunk_id":c.id, "source_id":c.source_id,
                             "title":c.source.title, "text":c.text, "similarity":s})
            if hits: return hits
        except Exception:
            pass
    terms = {t.lower() for t in re.findall(r"[a-zA-Z0-9]{3,}", query)}
    if not terms: return []
    scored = []
    for c in rows:
        toks = {t.lower() for t in re.findall(r"[a-zA-Z0-9]{3,}", c.text)}
        if not toks: continue
        ov = len(terms & toks) / max(1, len(terms))
        if ov > 0: scored.append((ov, c))
    scored.sort(key=lambda x: -x[0])
    return [{"chunk_id":c.id,"source_id":c.source_id,"title":c.source.title,
             "text":c.text,"similarity":float(s)} for s, c in scored[:top_k]]


# ═══════════════════════════════════════════════════════════════════════════
#  SEMANTIC LESSON SEARCH — "I don't know what this is called, but I need
#  help with ___" → the right lesson, anywhere in the curriculum. Distinct
#  from retrieve() above (which searches uploaded PDFs scoped to one
#  outcome): this searches every outcome's own name+blurb+concepts across
#  every course, so a vague or misspelled query can still land on the right
#  lesson. Embeddings are computed once per process and cached in memory —
#  cheap since the curriculum doesn't change after startup.
# ═══════════════════════════════════════════════════════════════════════════
_outcome_embed_cache: dict = {"vecs": None, "meta": None}

async def _outcome_search_corpus(db: Session) -> list[dict]:
    out = []
    for o in db.query(Outcome).all():
        concept_txt = " ".join(c.one_liner for c in o.concepts) if o.concepts else ""
        text = f"{o.name}. {o.blurb} {concept_txt}".strip()
        out.append({"outcome_id": o.id, "course_id": o.course_id, "strand": o.strand,
                    "name": o.name, "text": text})
    return out

async def semantic_lesson_search(db: Session, query: str, top_k: int = 5) -> list[dict]:
    corpus = await _outcome_search_corpus(db)
    if not corpus: return []
    alive, _, emb_ok = await ollama_alive()
    if alive and emb_ok:
        try:
            if _outcome_embed_cache["vecs"] is None or len(_outcome_embed_cache["meta"]) != len(corpus):
                vecs = await ollama_embed([c["text"] for c in corpus])
                _outcome_embed_cache["vecs"] = np.array(vecs, dtype=np.float32)
                _outcome_embed_cache["meta"] = corpus
            q_vec = (await ollama_embed([query]))[0]
            sims = cosine_sim(np.array(q_vec, dtype=np.float32), _outcome_embed_cache["vecs"])
            order = np.argsort(-sims)[:top_k]
            meta = _outcome_embed_cache["meta"]
            return [{**meta[i], "similarity": float(sims[i])} for i in order if sims[i] > 0.25]
        except Exception:
            pass
    # Keyword fallback — same degrade-gracefully pattern as retrieve().
    terms = {t.lower() for t in re.findall(r"[a-zA-Z0-9]{3,}", query)}
    if not terms: return []
    scored = []
    for c in corpus:
        toks = {t.lower() for t in re.findall(r"[a-zA-Z0-9]{3,}", c["text"])}
        ov = len(terms & toks) / max(1, len(terms))
        if ov > 0: scored.append((ov, c))
    scored.sort(key=lambda x: -x[0])
    return [{**c, "similarity": float(s)} for s, c in scored[:top_k]]


