@asynccontextmanager
async def _lifespan(_app: FastAPI):
    seed_if_empty()
    yield

app = FastAPI(title="Project X", lifespan=_lifespan)
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])


class MsgIn(BaseModel):
    role: Literal["system", "user", "assistant"]
    content: str

class ChatIn(BaseModel):
    outcome_id: str = ""     # empty string = free-form tutor (no specific outcome context)
    mode: Literal["practice", "homework"] = "practice"
    level: Literal["elementary", "secondary", "uni"] = "elementary"
    engine: Literal["auto", "ollama", "my_ai"] = "auto"
    messages: list[MsgIn]

class SubmitIn(BaseModel):
    outcome_id: str
    question_id: str
    answer: str
    hints_used: int = 0
    mode: Literal["practice", "flashcard", "rapid", "blitz", "diagnostic", "summary",
                  "unit-mini", "unit-final"] = "practice"

class PasteIn(BaseModel):
    title: str
    text: str
    outcome_id: str | None = None


def db_dep():
    d = SessionLocal()
    try: yield d
    finally: d.close()


@app.get("/")
def index(): return HTMLResponse(HTML_PAGE)

@app.get("/api/health")
async def health(db: Session = Depends(db_dep)):
    alive, chat_ok, emb_ok = await ollama_alive()
    return {"status":"ok","ollama_reachable":alive,"chat_model_ready":chat_ok,
            "embed_model_ready":emb_ok,"sources_indexed":db.query(Source).count(),
            "chunks_indexed":db.query(Chunk).count()}

@app.get("/api/courses")
def courses(db: Session = Depends(db_dep)):
    out = []
    for c in db.query(Course).order_by(Course.grade, Course.subject).all():
        outs = []
        for o in c.outcomes:
            outs.append({
                "id":o.id, "code":o.code, "name":o.name, "blurb":o.blurb, "strand":o.strand,
                "concepts":[{"id":co.id,"name":co.name,"sub":co.sub,"one_liner":co.one_liner,
                             "body":co.body,"worked":co.worked,"misconception":co.misconception} for co in o.concepts],
                "questions":[{"id":q.id,"kind":q.kind,"diff":q.diff,"prompt":q.prompt,
                              "choices":q.choices,"hints":q.hints,"answer":q.answer,
                              "solution":q.solution,"category":q.category} for q in o.questions],
            })
        out.append({"id":c.id, "label":c.label, "level":c.level, "grade":c.grade,
                    "subject":c.subject, "outcomes":outs})
    return out

@app.get("/api/conversations/{outcome_id}")
def get_conv(outcome_id: str): return CONVERSATIONS.get(outcome_id, [])

def _active_training(db: Session, outcome_id: str | None, limit: int = 6) -> list[dict]:
    """Global training examples + any scoped to this outcome, most recent first."""
    q = db.query(TrainingExample).filter(TrainingExample.active == True)
    if outcome_id:
        q = q.filter((TrainingExample.outcome_id == outcome_id) | (TrainingExample.outcome_id.is_(None)))
    else:
        q = q.filter(TrainingExample.outcome_id.is_(None))
    rows = q.order_by(TrainingExample.created_at.desc()).limit(limit).all()
    return [{"prompt":r.prompt, "response":r.response} for r in rows]


@app.post("/api/chat")
async def chat(payload: ChatIn, db: Session = Depends(db_dep)):
    last = next((m.content for m in reversed(payload.messages) if m.role == "user"), "")
    outcome = db.get(Outcome, payload.outcome_id) if payload.outcome_id else None
    if payload.outcome_id and not outcome:
        raise HTTPException(404, "outcome not found")
    training = _active_training(db, payload.outcome_id or None)
    if outcome:
        course = db.get(Course, outcome.course_id)
        retrieved = await retrieve(db, last, outcome_id=payload.outcome_id, top_k=3) if last else []
        system = build_system_prompt(payload.level, payload.mode, outcome.code, outcome.name,
                                     course.label, grade=course.grade, retrieved=retrieved, training=training)
    else:
        # Free-form tutor — no course pinned. Retrieval falls back to global sources only.
        retrieved = await retrieve(db, last, outcome_id=None, top_k=3) if last else []
        system = build_system_prompt(payload.level, payload.mode, "", "General tutoring",
                                     "General", grade=0, retrieved=retrieved, training=training)
    try:
        reply, provider = await chat_reply(system, [m.model_dump() for m in payload.messages],
                                           payload.mode, engine=payload.engine)
    except Exception as e:
        if payload.engine == "my_ai":
            reply, provider = f"My AI can't answer yet — {e}", "my_ai_error"
        else:
            raise
    db.add(LogEvent(kind="chat", detail=last[:120] if last else "", outcome_id=payload.outcome_id or None))
    db.commit()
    return {"reply":reply,"provider":provider,
            "citations":[{"source_id":r["source_id"],"title":r["title"],"chunk_id":r["chunk_id"],
                          "excerpt":r["text"][:280],"similarity":r["similarity"]} for r in retrieved]}


def update_mastery(db: Session, outcome_id: str, correct: bool, diff: int) -> float:
    """Exponential-moving-average mastery update (0-1 per outcome). A correct
    answer on a harder question (diff 4-5) pulls the score up more than an
    easy one; a wrong answer on an easy question pulls it down more than a
    wrong hard one — the intuition being an easy miss is a stronger signal
    of a gap than missing something genuinely hard. Learning rate is fixed
    at 0.20 so no single attempt can swing the score too far in one turn."""
    m = db.get(Mastery, outcome_id)
    if not m:
        m = Mastery(outcome_id=outcome_id, score=0.0, attempts=0, correct=0); db.add(m); db.flush()
    if m.score is None: m.score = 0.0
    if m.attempts is None: m.attempts = 0
    if m.correct is None: m.correct = 0
    target = 1.0 if correct else 0.0
    w = (0.5 + diff / 5.0) if correct else (1.5 - diff / 5.0)
    m.score = max(0.0, min(1.0, m.score + 0.20 * w * (target - m.score)))
    m.attempts += 1
    if correct: m.correct += 1
    m.updated_at = datetime.utcnow()
    db.commit()
    return m.score


@app.post("/api/attempts")
def submit_attempt(payload: SubmitIn, db: Session = Depends(db_dep)):
    q = db.get(Question, payload.question_id)
    if not q or q.outcome_id != payload.outcome_id:
        raise HTTPException(404, "question not found")
    correct = False
    if q.kind == "mc":
        try: correct = str(int(payload.answer)) == q.answer
        except ValueError: correct = False
    else:
        try:
            v = float(payload.answer.strip()); tgt = float(q.answer); tol = q.tolerance or 0.001
            correct = abs(v - tgt) <= tol
        except Exception: correct = False
    db.add(Attempt(outcome_id=payload.outcome_id, question_id=payload.question_id,
                   mode=payload.mode, correct=correct, hints_used=payload.hints_used))
    new_score = update_mastery(db, payload.outcome_id, correct, q.diff)
    db.add(LogEvent(kind=payload.mode,
                    detail=f"{q.id} · {'correct' if correct else 'wrong'} · {payload.hints_used} hints",
                    outcome_id=payload.outcome_id))
    db.commit()
    return {"correct":correct, "solution":q.solution, "mastery":new_score, "answer":q.answer}


@app.get("/api/mastery")
def get_mastery(db: Session = Depends(db_dep)):
    return [{"outcome_id":m.outcome_id,"score":m.score,"attempts":m.attempts,"correct":m.correct}
            for m in db.query(Mastery).all()]


@app.get("/api/semantic-search")
async def semantic_search_endpoint(q: str, db: Session = Depends(db_dep)):
    """'I don't know what this is called but I need help with ___' → the
    right lesson, anywhere in the curriculum. Real embedding-based semantic
    match (falls back to keyword overlap if Ollama isn't running)."""
    if not q.strip():
        return []
    hits = await semantic_lesson_search(db, q.strip())
    out = []
    for h in hits:
        course = db.get(Course, h["course_id"])
        if not course: continue
        out.append({"outcome_id": h["outcome_id"], "outcome_name": h["name"], "strand": h["strand"],
                    "course_id": course.id, "grade": course.grade, "subject": course.subject,
                    "course_label": course.label, "similarity": round(h["similarity"], 3)})
    return out


@app.get("/api/wrong-attempts")
def wrong_attempts(course_id: str, limit: int = 20, db: Session = Depends(db_dep)):
    """Return questions the student has answered wrong at least once, in this
    course. Powers the Summary quiz — compiles past mistakes to re-quiz on."""
    course = db.get(Course, course_id)
    if not course:
        raise HTTPException(404, "course not found")
    outcome_ids = [o.id for o in course.outcomes]
    if not outcome_ids:
        return []
    rows = db.query(Attempt).filter(
        Attempt.outcome_id.in_(outcome_ids),
        Attempt.correct == False,
    ).order_by(Attempt.created_at.desc()).all()
    seen = set()
    q_ids = []
    for a in rows:
        if a.question_id not in seen:
            seen.add(a.question_id)
            q_ids.append(a.question_id)
        if len(q_ids) >= limit:
            break
    if not q_ids:
        return []
    qs = db.query(Question).filter(Question.id.in_(q_ids)).all()
    q_map = {q.id: q for q in qs}
    result = []
    for qid in q_ids:  # preserve most-recent-first order
        q = q_map.get(qid)
        if not q:
            continue
        result.append({
            "id": q.id, "kind": q.kind, "diff": q.diff, "prompt": q.prompt,
            "choices": q.choices, "hints": q.hints, "solution": q.solution,
            "answer": q.answer, "outcome_id": q.outcome_id,
            "unit": q.outcome.strand, "category": q.category,
        })
    return result


@app.get("/api/sources")
def list_sources(db: Session = Depends(db_dep)):
    return [{"id":s.id,"title":s.title,"kind":s.kind,"bytes_size":s.bytes_size,
             "chunks_n":s.chunks_n,"outcome_id":s.outcome_id,"created_at":s.created_at.isoformat()}
            for s in db.query(Source).order_by(Source.created_at.desc()).all()]


async def _persist_and_embed(db: Session, title: str, kind: str, text: str,
                             outcome_id: str | None, bytes_size: int) -> Source:
    if not text.strip(): raise HTTPException(400, "no readable text")
    src = Source(title=title, kind=kind, outcome_id=outcome_id, bytes_size=bytes_size)
    db.add(src); db.flush()
    pieces = chunk_text(text)
    chunks = [Chunk(source_id=src.id, outcome_id=outcome_id, ord=i, text=p) for i, p in enumerate(pieces)]
    db.add_all(chunks)
    src.chunks_n = len(chunks); db.commit()
    try:
        vecs = await ollama_embed([c.text for c in chunks])
        for c, v in zip(chunks, vecs): c.embedding = v
        db.commit()
    except Exception:
        pass
    return src


@app.post("/api/sources/paste")
async def paste_source(payload: PasteIn, db: Session = Depends(db_dep)):
    src = await _persist_and_embed(db, title=payload.title or "Pasted note", kind="paste",
                                   text=payload.text, outcome_id=payload.outcome_id,
                                   bytes_size=len(payload.text.encode("utf-8")))
    db.add(LogEvent(kind="teach", detail=f"pasted · {src.title} · {src.chunks_n} chunks",
                    outcome_id=payload.outcome_id))
    db.commit()
    return {"id":src.id,"title":src.title,"kind":src.kind,"bytes_size":src.bytes_size,
            "chunks_n":src.chunks_n,"outcome_id":src.outcome_id,"created_at":src.created_at.isoformat()}


@app.post("/api/sources/upload")
async def upload_source(file: UploadFile = File(...), outcome_id: str | None = Form(None),
                        db: Session = Depends(db_dep)):
    if not file.filename: raise HTTPException(400, "no file")
    ext = Path(file.filename).suffix.lower().lstrip(".")
    if ext not in {"pdf", "docx", "txt", "md"}:
        raise HTTPException(400, f"can't handle .{ext}")
    dest = UPLOAD_DIR / f"{int(datetime.utcnow().timestamp())}_{file.filename}"
    with dest.open("wb") as f: shutil.copyfileobj(file.file, f)
    try: text = extract_text(dest, ext)
    except Exception as e: raise HTTPException(400, f"couldn't read: {e}") from e
    src = await _persist_and_embed(db, title=file.filename, kind=ext, text=text,
                                   outcome_id=outcome_id, bytes_size=dest.stat().st_size)
    db.add(LogEvent(kind="teach", detail=f"uploaded · {file.filename} · {src.chunks_n} chunks",
                    outcome_id=outcome_id))
    db.commit()
    return {"id":src.id,"title":src.title,"kind":src.kind,"bytes_size":src.bytes_size,
            "chunks_n":src.chunks_n,"outcome_id":src.outcome_id,"created_at":src.created_at.isoformat()}


@app.delete("/api/sources/{sid}")
def delete_source(sid: int, db: Session = Depends(db_dep)):
    s = db.get(Source, sid)
    if not s: raise HTTPException(404, "not found")
    db.delete(s); db.commit()
    return {"ok": True}


# ═════════════════════════════════════════════════════════════════════════════
#  TRAINING STUDIO — persistent, hand-taught Q&A pairs. This is the realistic
#  version of "training the AI" for a local model: not fine-tuning weights,
#  but a growing library of example answers that gets fed into every chat's
#  system prompt (see _active_training / build_system_prompt).
# ═════════════════════════════════════════════════════════════════════════════
class TrainingIn(BaseModel):
    prompt: str
    response: str
    note: str = ""
    outcome_id: str | None = None

@app.get("/api/training")
def list_training(outcome_id: str | None = None, db: Session = Depends(db_dep)):
    q = db.query(TrainingExample)
    if outcome_id:
        q = q.filter((TrainingExample.outcome_id == outcome_id) | (TrainingExample.outcome_id.is_(None)))
    rows = q.order_by(TrainingExample.created_at.desc()).all()
    return [{"id":r.id, "prompt":r.prompt, "response":r.response, "note":r.note,
             "outcome_id":r.outcome_id, "active":r.active, "created_at":r.created_at.isoformat()}
            for r in rows]

@app.post("/api/training")
def add_training(payload: TrainingIn, db: Session = Depends(db_dep)):
    if not payload.prompt.strip() or not payload.response.strip():
        raise HTTPException(400, "prompt and response are both required")
    row = TrainingExample(prompt=payload.prompt.strip(), response=payload.response.strip(),
                          note=payload.note.strip(), outcome_id=payload.outcome_id, active=True)
    db.add(row)
    db.add(LogEvent(kind="training", detail=f"taught · {payload.prompt[:80]}", outcome_id=payload.outcome_id))
    db.commit()
    return {"id":row.id, "prompt":row.prompt, "response":row.response, "note":row.note,
            "outcome_id":row.outcome_id, "active":row.active, "created_at":row.created_at.isoformat()}

@app.patch("/api/training/{tid}")
def toggle_training(tid: int, db: Session = Depends(db_dep)):
    row = db.get(TrainingExample, tid)
    if not row: raise HTTPException(404, "not found")
    row.active = not row.active
    db.commit()
    return {"id":row.id, "active":row.active}

@app.delete("/api/training/{tid}")
def delete_training(tid: int, db: Session = Depends(db_dep)):
    row = db.get(TrainingExample, tid)
    if not row: raise HTTPException(404, "not found")
    db.delete(row); db.commit()
    return {"ok": True}


# ── My AI — the local from-scratch model: status, train, and a dedicated
#    reply endpoint so the Training Studio's test pane can force this engine
#    even when Ollama is also running. ──
@app.get("/api/my-ai/status")
def my_ai_status():
    status = myai_status()
    status["training_now"] = _myai_train_state["running"]
    status["progress"] = _myai_train_state["progress"]
    status["last_loss"] = _myai_train_state["loss"]
    status["last_error"] = _myai_train_state["error"]
    return status

@app.post("/api/my-ai/train")
def my_ai_train(db: Session = Depends(db_dep)):
    if not TORCH_OK:
        raise HTTPException(400, "PyTorch isn't installed — run: pip install torch")
    if _myai_train_state["running"]:
        raise HTTPException(409, "already training")
    def _run():
        with SessionLocal() as tdb:
            try:
                myai_train_sync(tdb, epochs=8)
            except Exception:
                pass
    threading.Thread(target=_run, daemon=True).start()
    return {"started": True}


@app.get("/api/log")
def get_log(limit: int = 200, db: Session = Depends(db_dep)):
    rows = db.query(LogEvent).order_by(LogEvent.created_at.desc()).limit(limit).all()
    return [{"id":r.id,"kind":r.kind,"detail":r.detail,"outcome_id":r.outcome_id,
             "created_at":r.created_at.isoformat()} for r in rows]


@app.delete("/api/log")
def clear_log(db: Session = Depends(db_dep)):
    db.query(LogEvent).delete(); db.commit(); return {"ok": True}


